use gpui::{App, ClipboardItem, WindowOptions, div, prelude::*};
use gpui_platform::application;

struct ClipboardDoctor {
    report: String,
}

impl Render for ClipboardDoctor {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .id("root")
            .p_4()
            .flex()
            .flex_col()
            .gap_2()
            .child(self.button("① 写入并同步读回", Self::check_roundtrip))
            .child(self.button("② 异步读回", Self::check_async))
            .child(self.button("③ 主选区", Self::check_primary))
            .child(self.button("④ 文件对话框", Self::check_file_dialog))
            .child(div().child(self.report.clone()))
    }
}

impl ClipboardDoctor {
    fn button(
        &mut self,
        label: &str,
        mut handler: impl FnMut(&mut Self, &mut Window, &mut Context<Self>) + 'static,
    ) -> impl IntoElement + use<> {
        div()
            .id(label.to_string())
            .cursor_pointer()
